"""Verify that a non-TLS connection to the Redis ports does not speak RESP."""
import socket

def probe(port):
    s = socket.create_connection(("127.0.0.1", port), timeout=5)
    s.sendall(b"PING\r\n")
    try:
        data = s.recv(256)
    except (ConnectionResetError, socket.timeout) as e:
        s.close()
        return f"no RESP reply ({type(e).__name__})", b""
    s.close()
    if data == b"":
        return "no RESP reply (peer closed, empty read)", data
    # A plaintext Redis server would answer "+PONG\r\n".
    if data.startswith(b"+") or data.startswith(b"-") or data.startswith(b"$"):
        return "SPOKE RESP -- FAIL", data
    return "non-RESP bytes (TLS alert)", data

for port in (6379, 6380):
    verdict, raw = probe(port)
    print(f"port {port}: {verdict}  raw={raw!r}")

